<!-- generated by studio，请勿手工修改。 -->
<template>
  <ContentWrap>
    <el-form ref="queryFormRef" :inline="true" :model="queryParams" class="-mb-15px">
        <el-form-item label="项目名称" prop="projectName">
          <el-input v-model="queryParams.projectName" clearable placeholder="请输入项目名称" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="项目所属区域名称" prop="areaName">
          <el-input v-model="queryParams.areaName" clearable placeholder="请输入项目所属区域名称" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="项目地址" prop="projectAddress">
          <el-input v-model="queryParams.projectAddress" clearable placeholder="请输入项目地址" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="送检公司名称" prop="nameOfInspectionCompany">
          <el-input v-model="queryParams.nameOfInspectionCompany" clearable placeholder="请输入送检公司名称" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="送检单位地址" prop="addressOfTheInspectionUnit">
          <el-input v-model="queryParams.addressOfTheInspectionUnit" clearable placeholder="请输入送检单位地址" @keyup.enter="handleQuery" />
        </el-form-item>
        <el-form-item label="送检单位邮箱" prop="emailAddressOfTheInspectionUnit">
          <el-input v-model="queryParams.emailAddressOfTheInspectionUnit" clearable placeholder="请输入送检单位邮箱" @keyup.enter="handleQuery" />
        </el-form-item>
      <el-form-item>
        <el-button @click="handleQuery"><Icon class="mr-5px" icon="ep:search" />查询</el-button>
        <el-button @click="resetQuery"><Icon class="mr-5px" icon="ep:refresh" />重置</el-button>
          <el-button type="primary" @click="openForm('create')">
            <Icon class="mr-5px" icon="ep:plus" />新增
          </el-button>
          <el-button :loading="exportLoading" type="success" @click="handleExport">
            <Icon class="mr-5px" icon="ep:download" />导出
          </el-button>
          <el-button :disabled="checkedIds.length === 0" type="danger" @click="handleDeleteBatch">
            <Icon class="mr-5px" icon="ep:delete" />批量删除
          </el-button>
      </el-form-item>
    </el-form>
  </ContentWrap>

  <ContentWrap>
    <el-table v-loading="loading" :data="rows" @selection-change="handleSelectionChange">
        <el-table-column align="center" type="selection" width="55" />
      <el-table-column align="center" label="行号" width="90">
        <template #default="scope">{{ (queryParams.pageNo - 1) * queryParams.pageSize + scope.$index + 1 }}</template>
      </el-table-column>
        <el-table-column label="项目名称" prop="projectName" min-width="120" show-overflow-tooltip />
        <el-table-column label="项目类型" prop="projectType" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" :formatter="dateFormatter" label="开工日期" prop="startDate" width="180" />
        <el-table-column align="center" :formatter="dateFormatter" label="竣工日期" prop="completionDate" width="180" />
        <el-table-column label="工程进度" prop="engineeringProgress" min-width="120" show-overflow-tooltip />
        <el-table-column label="项目所属区域编码" prop="areaCode" min-width="120" show-overflow-tooltip />
        <el-table-column label="项目所属区域名称" prop="areaName" min-width="120" show-overflow-tooltip />
        <el-table-column label="项目地址" prop="projectAddress" min-width="120" show-overflow-tooltip />
        <el-table-column label="送检公司名称" prop="nameOfInspectionCompany" min-width="120" show-overflow-tooltip />
        <el-table-column label="送检单位地址" prop="addressOfTheInspectionUnit" min-width="120" show-overflow-tooltip />
        <el-table-column label="送检单位邮箱" prop="emailAddressOfTheInspectionUnit" min-width="120" show-overflow-tooltip />
        <el-table-column align="center" fixed="right" label="操作" width="160">
          <template #default="scope">
            <el-button link type="primary" @click="openDetail(scope.row.id)">查看</el-button>
            <el-button link type="primary" @click="openForm('update', scope.row.id)">编辑</el-button>
            <el-button link type="danger" @click="handleDelete(scope.row.id)">删除</el-button>
          </template>
        </el-table-column>
    </el-table>
    <Pagination v-model:limit="queryParams.pageSize" v-model:page="queryParams.pageNo" :total="total" @pagination="getList" />
  </ContentWrap>

  <BoxunProjectInfoForm ref="formRef" @success="getList" />
  <BoxunProjectInfoDetail ref="detailRef" />
</template>

<script setup lang="ts">
import { dateFormatter } from '@/utils/formatTime'
import request from '@/config/axios'
import download from '@/utils/download'
import * as BoxunProjectInfoApi from './BoxunProjectInfoApi'
import BoxunProjectInfoForm from './BoxunProjectInfoForm.vue'
import BoxunProjectInfoDetail from './BoxunProjectInfoDetail.vue'

type BoxunProjectInfoRow = Awaited<ReturnType<typeof BoxunProjectInfoApi.getBoxunProjectInfoPage>>['list'][number]
type EntityId = string | number

defineOptions({ name: 'BoxunProjectInfo' })

const message = useMessage()
const { t } = useI18n()
const loading = ref(false)
const total = ref(0)
const rows = ref<BoxunProjectInfoRow[]>([])
const queryFormRef = ref()
const queryParams = reactive({
  pageNo: 1,
  pageSize: 10,
  projectName: '',
  areaName: '',
  projectAddress: '',
  nameOfInspectionCompany: '',
  addressOfTheInspectionUnit: '',
  emailAddressOfTheInspectionUnit: ''
})



const getList = async () => {
  loading.value = true
  try {
    const data = await BoxunProjectInfoApi.getBoxunProjectInfoPage(queryParams)
    rows.value = data.list
    total.value = Number(data.total)
  } finally {
    loading.value = false
  }
}

const handleQuery = () => {
  queryParams.pageNo = 1
  getList()
}

const resetQuery = () => {

  queryFormRef.value?.resetFields()

  handleQuery()
}

const formRef = ref()
const openForm = (type: 'create' | 'update', id?: EntityId) => {
  formRef.value?.open(type, id, type === 'create' ? undefined : undefined)
}


const detailRef = ref()
const openDetail = (id: EntityId) => {
  detailRef.value?.open(id)
}



const handleDelete = async (id?: EntityId) => {
  if (id === undefined) return
  await message.delConfirm()
  await BoxunProjectInfoApi.deleteBoxunProjectInfo(id)
  message.success(t('common.delSuccess'))
  await getList()
}

const checkedIds = ref<EntityId[]>([])
const handleSelectionChange = (rows: BoxunProjectInfoRow[]) => {
  checkedIds.value = rows.map((row) => row.id).filter((id): id is EntityId => id !== undefined)
}

const handleDeleteBatch = async () => {
  await message.delConfirm()
  await BoxunProjectInfoApi.deleteBoxunProjectInfoList(checkedIds.value)
  message.success(t('common.delSuccess'))
  checkedIds.value = []
  await getList()
}
const exportLoading = ref(false)
const handleExport = async () => {
  await message.exportConfirm()
  exportLoading.value = true
  try {
    const data = await request.download({ url: '/boxun/project-info/export-excel', params: queryParams })
    download.excel(data, 'boxunProjectInfo.xls')
  } finally {
    exportLoading.value = false
  }
}

onMounted(getList)
</script>
